let lang=localStorage.getItem('rdw-lang')||'nl';if(!LANGS[lang])lang='nl';const t=(k)=>ORIGIN_LABELS[lang]?.[k]||LANGS[lang][k]||LANGS.en[k]||k;const esc=(v='')=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const app=document.getElementById('app');let page=document.body.dataset.page;
function header(){return `<div class="top-note">${esc(t('prototypeBanner'))}</div><header class="header"><div class="wrap nav"><a class="brand" href="/"><span class="brand-mark" aria-hidden="true">🐾</span><span class="brand-text">Haneul Tails Rescue<small>Rescue. Rehabilitate. Rehome.</small></span></a><nav class="nav-links" aria-label="Main navigation"><a href="/">${t('home')}</a><a href="/dogs.html">${t('dogs')}</a><a href="/adoption.html">${t('adoptionInfo')}</a><a href="/review.html">${t('review')}</a></nav><div class="nav-right"><label class="sr-only" for="language">${t('lang')}</label><select class="lang-select" id="language" aria-label="${t('lang')}"><option value="nl">NL</option><option value="fr">FR</option><option value="de">DE</option><option value="en">EN</option></select><a class="button small" href="/dogs.html">${t('meet')} <span aria-hidden="true">→</span></a></div></div></header>`}
function footer(){return `<footer class="footer"><div class="wrap footer-grid"><div><strong>Haneul Tails Rescue</strong><p>${esc(t('placeholderOrg'))}</p><p class="tiny">${esc(t('footerText'))}</p></div><p class="tiny" style="max-width:570px">${esc(t('privacy'))}</p></div></footer>${window.whatsappButton?window.whatsappButton():''}`}
function shell(content){document.documentElement.lang=lang;app.setAttribute('aria-busy','false');app.innerHTML=header()+content+footer();const sel=document.getElementById('language');sel.value=lang;sel.addEventListener('change',()=>{lang=sel.value;localStorage.setItem('rdw-lang',lang);runTransition(()=>render())})}
let transitionRunning=false,queuedTransition=null;
function runTransition(update){if(typeof document.startViewTransition!=='function'||window.matchMedia('(prefers-reduced-motion: reduce)').matches||document.visibilityState==='hidden')return update();if(transitionRunning){queuedTransition=update;return}let transition;try{transitionRunning=true;transition=document.startViewTransition(update)}catch{transitionRunning=false;return update()}const finish=()=>{transitionRunning=false;const queued=queuedTransition;queuedTransition=null;if(queued)runTransition(queued)};transition.finished.then(finish,finish);return transition}
function dogViewName(d){return `dog-photo-${String(d.id||'dog').replace(/[^a-z0-9_-]/gi,'-')}`}
function dogPhotoSources(d){const values=[...(Array.isArray(d.photos)?d.photos:[]),d.photo].map(item=>typeof item==='string'?item:item&&typeof item.src==='string'?item.src:'').filter(src=>src.startsWith('/')&&!src.startsWith('//')&&!src.includes('..'));return [...new Set(values)]}
function photo(d,small=false){const src=dogPhotoSources(d)[0];const alt=d.example?esc(d.name):`${esc(d.name)} - ${esc(d.temperament||'rescue dog')}`;const image=src?`<img src="${esc(src)}" alt="${alt}">`:`<span class="emoji" aria-hidden="true">🐕</span>`;return `<div class="dog-photo ${small?'small':''}" style="view-transition-name:${dogViewName(d)}">${image}${d.example?`<span class="badge">${esc(t('testLabel'))}</span>`:''}</div>`}
