const ft=k=>FORM_LABELS[lang]?.[k]||FORM_LABELS.en[k]||k;
function profileRows(d){const origin=['China','South Korea'].includes(d.originCountry)?d.originCountry:'';const age=d.age?`${d.ageEstimated===true?`${dt('estimated')} `:''}${d.age}`:'';const fields=[[t('age'),age],[t('size'),d.size],[t('breed'),d.breed],[dt('origin'),origin],[t('location'),d.location],[dt('physical'),d.physicalDetails],[t('temperament'),d.temperament],[t('health'),d.example?d.health:(d.healthConfirmed===true?d.health:'')],[dt('medical'),d.example?d.medicalNeeds:(d.medicalNeedsConfirmed===true?d.medicalNeeds:'')],[t('needs'),d.needs],[t('homeFit'),d.home]];const rows=fields.filter(([,value])=>typeof value==='string'&&value.trim()).map(([label,value])=>`<div class="detail"><strong>${esc(label)}</strong>${esc(value)}</div>`);const compatibility=d.compatibility&&typeof d.compatibility==='object'?[[dt('children'),d.compatibility.children],[dt('dogs'),d.compatibility.dogs],[dt('cats'),d.compatibility.cats]].filter(([,value])=>typeof value==='string'&&value.trim()):[];if(compatibility.length)rows.push(`<div class="detail compatibility-detail"><strong>${esc(dt('compatibility'))}</strong>${compatibility.map(([label,value])=>`<span><b>${esc(label)}:</b> ${esc(value)}</span>`).join('')}</div>`);return rows.join('')}
function profileHealth(d){const rows=[];const vaccination=['vaccinated','not-vaccinated','pending'].includes(d.vaccinationStatus)?d.vaccinationStatus:'';if(d.vaccinationStatusConfirmed===true&&vaccination)rows.push([dt('vaccination'),vaccination==='not-vaccinated'?dt('notVaccinated'):vaccination==='pending'?dt('pending'):dt('vaccinated')]);else if(d.vaccinatedConfirmed===true)rows.push([dt('vaccination'),dt('vaccinated')]);const documentation=['valid','invalid','pending'].includes(d.documentationStatus)?d.documentationStatus:'';if(d.documentationStatusConfirmed===true&&documentation)rows.push([dt('documentation'),documentation==='invalid'?dt('invalidDocs'):documentation==='pending'?dt('pending'):dt('validDocs')]);else if(d.documentationConfirmed===true)rows.push([dt('documentation'),dt('validDocs')]);const healthLabels={nl:{vaccination:'Vaccinaties',microchip:'Chip',sterilisation:'Sterilisatie',deworming:'Ontworming',fleaTreatment:'Vlooienbehandeling',documentation:'Reisdocumenten',unknown:'Onbekend',pending:'In afwachting',noVaccination:'Niet gevaccineerd',vaccinated:'Gevaccineerd',noChip:'Niet gechipt',microchipped:'Geïmplanteerd',noSterilisation:'Niet gesteriliseerd',sterilised:'Gesteriliseerd',noTreatment:'Niet behandeld',treated:'Behandeld',invalid:'Ongeldig'},en:{vaccination:'Vaccinations',microchip:'Microchip',sterilisation:'Sterilisation',deworming:'Deworming',fleaTreatment:'Flea treatment',documentation:'Travel documents',unknown:'Unknown',pending:'Pending',noVaccination:'Not vaccinated',vaccinated:'Vaccinated',noChip:'Not microchipped',microchipped:'Implanted',noSterilisation:'Not sterilised',sterilised:'Sterilised',noTreatment:'Not treated',treated:'Treated',invalid:'Invalid'},fr:{vaccination:'Vaccinations',microchip:'Puce électronique',sterilisation:'Stérilisation',deworming:'Vermifuge',fleaTreatment:'Traitement antipuces',documentation:'Documents de voyage',unknown:'Inconnu',pending:'En attente',noVaccination:'Non vacciné',vaccinated:'Vacciné',noChip:'Non identifié par puce',microchipped:'Puce implantée',noSterilisation:'Non stérilisé',sterilised:'Stérilisé',noTreatment:'Non traité',treated:'Traité',invalid:'Invalide'},de:{vaccination:'Impfungen',microchip:'Mikrochip',sterilisation:'Sterilisation',deworming:'Entwurmung',fleaTreatment:'Flohbehandlung',documentation:'Reisedokumente',unknown:'Unbekannt',pending:'Ausstehend',noVaccination:'Nicht geimpft',vaccinated:'Geimpft',noChip:'Nicht gechippt',microchipped:'Implantiert',noSterilisation:'Nicht sterilisiert',sterilised:'Sterilisiert',noTreatment:'Nicht behandelt',treated:'Behandelt',invalid:'Ungültig'}};const labels=healthLabels[lang]||healthLabels.en;const statusRows=[['vaccination','vaccinationStatus','vaccinationStatusConfirmed',['vaccinated','not-vaccinated','pending','unknown']],['microchip','microchipStatus','microchipStatusConfirmed',['microchipped','not-microchipped','pending','unknown']],['sterilisation','sterilisationStatus','sterilisationStatusConfirmed',['sterilised','not-sterilised','pending','unknown']],['deworming','dewormingStatus','dewormingStatusConfirmed',['treated','not-treated','pending','unknown']],['fleaTreatment','fleaTreatmentStatus','fleaTreatmentStatusConfirmed',['treated','not-treated','pending','unknown']],['documentation','documentationStatus','documentationStatusConfirmed',['valid','invalid','pending','unknown']]];for(const [key,property,verified,allowed] of statusRows){const status=d[property];const label=key==='vaccination'?dt('vaccination'):key==='documentation'?dt('documentation'):labels[key];if(d[verified]!==true||!allowed.includes(status)||rows.some(([existing])=>existing===label))continue;const value=status==='pending'?labels.pending:status==='unknown'?labels.unknown:status==='vaccinated'?labels.vaccinated:status==='not-vaccinated'?labels.noVaccination:status==='microchipped'?labels.microchipped:status==='not-microchipped'?labels.noChip:status==='sterilised'?labels.sterilised:status==='not-sterilised'?labels.noSterilisation:status==='treated'?labels.treated:status==='not-treated'?labels.noTreatment:status==='invalid'?labels.invalid:status==='valid'?dt('validDocs'):status;rows.push([label,value])}return rows.length?`<aside class="health-confirmed" aria-label="${esc(t('healthDocsTitle'))}">${rows.map(([label,value])=>`<div class="health-item"><strong>${esc(label)}</strong><span>${esc(value)}</span></div>`).join('')}</aside>`:''}
function profileGallery(d,example){const photos=dogPhotoSources(d);const image=photos.length?`<img id="profile-main-photo" src="${esc(photos[0])}" alt="${esc(d.name)}">`:`<span class="emoji" aria-hidden="true">🐕</span>`;const thumbs=photos.length>1?`<div class="photo-thumbnails" role="group" aria-label="${esc(dt('photos'))}">${photos.map((src,i)=>`<button type="button" class="photo-thumb${i===0?' is-active':''}" data-photo-index="${i}" aria-pressed="${i===0?'true':'false'}" aria-label="${esc(dt('showPhoto'))} ${i+1}"><img src="${esc(src)}" alt=""></button>`).join('')}</div>`:'';return `<div class="profile-gallery"><div class="profile-photo" style="view-transition-name:${dogViewName(d)}">${image}${example?`<span class="badge">${esc(t('testLabel'))}</span>`:''}</div>${thumbs}</div>`}
function enquiryFormMarkup(dogs=[],selectedDogId='suggestions'){const query=selectedDogId&&selectedDogId!=='suggestions'?`?dogId=${encodeURIComponent(selectedDogId)}`:'';return `<section id="enquiry" class="form-card adoption-form-card"><h2>${esc(t('formTitle'))}</h2><p class="muted">${esc(t('formIntro'))}</p><p class="privacy-note">${esc(ft('privacyNote'))}</p><a class="button" href="/application.html${query}">${esc(t('adopt'))} →</a></section>`}
function bindEnquiryForm(){const form=document.getElementById('enquiry');if(!form)return;const country=document.getElementById('country-residence'),otherField=document.getElementById('other-country-field'),otherInput=document.getElementById('other-country'),result=document.getElementById('form-result'),button=form.querySelector('button[type="submit"]');const updateOther=()=>{const show=country.value==='other';otherField.hidden=!show;otherInput.required=show;if(!show)otherInput.value=''};country.addEventListener('change',updateOther);form.addEventListener('submit',async event=>{event.preventDefault();if(!form.reportValidity())return;result.className='';result.textContent='';button.disabled=true;const body=Object.fromEntries(new FormData(form));body.language=lang;try{const statusResponse=await fetch('/api/status');if(!statusResponse.ok||!(await statusResponse.json()).secureEnquiries)throw new Error('secure storage unavailable');const response=await fetch('/api/enquiries',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!response.ok)throw new Error('save failed');const saved=await response.json();if(!saved.saved||saved.delivery!=='encrypted-local-inbox')throw new Error('save failed');result.className='success';result.textContent=ft('saved');form.reset();updateOther()}catch{result.className='danger';result.textContent=ft('failure')}finally{button.disabled=false}});updateOther()}
function card(d){return `<article class="dog-card"><a href="/dog/${encodeURIComponent(d.id)}" aria-label="${esc(t('profile'))}: ${esc(d.name)}">${photo(d)}</a><div class="dog-card-body"><h3>${esc(d.name)}</h3><div class="meta">${esc(d.age||'')} · ${esc(d.breed||'')}</div><p>${esc(d.description||d.temperament||'')}</p><div class="card-actions"><span class="meta">${esc(d.location||'')}</span><a class="button secondary small" href="/dog/${encodeURIComponent(d.id)}">${esc(t('profile'))} →</a></div></div></article>`}
async function getDogs(endpoint='/api/dogs'){const r=await fetch(endpoint);if(!r.ok)throw new Error('Request failed');return r.json()}
async function home(){let dogs=[];try{dogs=await getDogs()}catch{}const available=dogs.filter(d=>d.status==='available'&&!d.example);const examples=dogs.filter(d=>d.example||d.status==='example');shell(`<main><section class="hero"><div class="wrap hero-grid"><div><div class="eyebrow">${esc(t('heroKicker'))}</div><h1>${esc(t('heroTitle'))}</h1><p>${esc(t('heroText'))}</p><div class="hero-actions"><a class="button" href="/dogs.html">${esc(t('meet'))} →</a><a class="button secondary" href="#about">${esc(t('how'))}</a></div></div><div class="hero-art" aria-label="Illustration of a dog"><span class="hero-dog" aria-hidden="true">🐕</span><div class="hero-stamp">A home for every heart ♡</div></div></div></section><section class="section"><div class="wrap"><div class="section-head"><div><div class="eyebrow">${esc(t('featured'))}</div><h2 class="section-title">${esc(t('featuredSub'))}</h2></div><a href="/dogs.html" class="button secondary">${esc(t('allDogs'))} →</a></div>${available.length?`<div class="cards">${available.slice(0,3).map(card).join('')}</div>`:`<div class="empty-state">${esc(t('noDogs'))}</div>`}</div></section><section class="section story-section" id="about"><div class="wrap story-grid"><div class="story-copy"><div class="eyebrow">${esc(t('storyLabel'))}</div><h2 class="section-title">${esc(t('storyTitle'))}</h2><p>${esc(t('storyCopy'))}</p><div class="origin-chips"><span>China</span><span>South Korea</span><span>Belgium</span><span>Netherlands</span><span>Luxembourg</span></div></div><figure class="story-art"><div class="story-art-inner"><span class="story-sun" aria-hidden="true"></span><span class="story-dog" aria-hidden="true">🐕</span><div class="story-art-tag">${esc(t('originsLabel'))}</div></div><figcaption>${esc(t('storyImageCaption'))}</figcaption></figure></div></section><section class="section test-section"><div class="wrap"><div class="notice"><strong>${esc(t('examples'))}</strong><br>${esc(t('exampleNotice'))}</div>${examples.length?`<div class="cards" style="margin-top:20px">${examples.map(card).join('')}</div>`:''}</div></section></main>`)}
async function dogsPage(){let dogs=[];try{dogs=await getDogs()}catch{}const real=dogs.filter(d=>d.status==='available'&&!d.example);const examples=dogs.filter(d=>d.example||d.status==='example');const happyTails=dogs.filter(d=>d.status==='adopted'&&d.adopterTestimonial).slice(0,3);shell(`<main class="wrap"><button type="button" class="filter-toggle" id="filter-toggle" aria-expanded="false">${esc(t('search'))} + <span class="toggle-icon">+</span></button><section class="page-hero"><div class="eyebrow">Haneul Tails Rescue</div><h1 class="section-title">${esc(t('available'))}</h1><p class="muted">${esc(t('availableIntro'))}</p><a class="button" href="#enquiry">${esc(t('adopt'))}</a></section><div class="filter-panel" id="filter-panel"><div class="field"><label for="q">${esc(t('search'))}</label><input id="q" type="search" placeholder="${esc(t('search'))}"></div><div class="field"><label for="size">${esc(t('size'))}</label><select id="size"><option value="">${esc(t('allSizes'))}</option><option value="small">${esc(t('small'))}</option><option value="medium">${esc(t('medium'))}</option><option value="large">${esc(t('large'))}</option></select></div><div class="field"><label for="country">${esc(t('country'))}</label><select id="country"><option value="">${esc(t('allCountries'))}</option><option value="Belgium">Belgium</option><option value="Netherlands">Netherlands</option><option value="Luxembourg">Luxembourg</option></select></div><div class="field"><label for="origin">${esc(t('origin'))}</label><div class="origin-select-wrap"><span class="origin-placeholder" id="origin-placeholder" aria-hidden="true">${esc(t('allOrigins'))}</span><select id="origin" aria-describedby="origin-hint"><option value="China">China</option><option value="South Korea">South Korea</option></select></div><span class="visually-hidden" id="origin-hint">${esc(ORIGIN_LABELS[lang].hint)}</span><button id="clear-origin" class="clear-filter" type="button">${esc(t('allOrigins'))}</button></div></div><div id="results" class="cards"></div><div class="section"><div class="notice"><strong>${esc(t('examples'))}</strong><br>${esc(t('exampleNotice'))}</div><div class="cards" style="margin-top:20px">${examples.map(card).join('')||''}</div></div>${enquiryFormMarkup(real)}</main>`);const results=document.getElementById('results');const q=document.getElementById('q'),size=document.getElementById('size'),country=document.getElementById('country'),origin=document.getElementById('origin'),clearOrigin=document.getElementById('clear-origin');const filterToggle=document.getElementById('filter-toggle');const filterPanel=document.getElementById('filter-panel');if(filterToggle&&filterPanel&&window.innerWidth<760){filterPanel.classList.add('mobile-collapsed')}origin.selectedIndex=-1;function update(animate=true){const term=q.value.toLowerCase();const found=real.filter(d=>(!term||`${d.name} ${d.breed} ${d.location} ${d.description}`.toLowerCase().includes(term))&&(!size.value||d.size===size.value)&&(!country.value||String(d.location).toLowerCase().includes(country.value.toLowerCase()))&&(!origin.value||d.originCountry===origin.value));const html=found.length?found.map(card).join(''):`<div class="empty-state" style="grid-column:1/-1">${esc(real.length?t('noMatch'):t('noDogs'))}</div>`;const commit=()=>{results.innerHTML=html};if(animate)runTransition(commit);else commit()}let searchTimer=0;q.addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>update(true),160)});[size,country].forEach(control=>control.addEventListener('change',()=>update(true)));origin.addEventListener('change',()=>{document.getElementById('origin-placeholder').hidden=Boolean(origin.value);update(true)});clearOrigin.addEventListener('click',()=>{origin.selectedIndex=-1;document.getElementById('origin-placeholder').hidden=false;update(true)});if(filterToggle&&filterPanel){filterToggle.addEventListener('click',()=>{const open=filterPanel.classList.toggle('open');filterToggle.classList.toggle('open',open);filterToggle.setAttribute('aria-expanded',String(open));const icon=filterToggle.querySelector('.toggle-icon');if(icon)icon.textContent=open?'−':'+'})}update(false);bindEnquiryForm()}async function profilePage(){let dogId=new URLSearchParams(location.search).get('id');if(!dogId){const match=location.pathname.match(/^\/dog\/([a-zA-Z0-9_-]+)$/);if(match)dogId=decodeURIComponent(match[1])}let dogs=[];try{dogs=await getDogs('/api/all-dogs')}catch{try{dogs=await getDogs()}catch{}}const d=dogs.find(x=>x.id===dogId);if(!d){shell(`<main class="wrap section"><div class="empty-state">${esc(t('noDogs'))}<p><a class="button" href="/dogs.html">${esc(t('back'))}</a></p></div></main>`);return}const example=d.example||d.status==='example';const available=d.status==='available'&&!example;const photoSources=dogPhotoSources(d);const dogUrl=`/dog/${encodeURIComponent(d.id)}`;const createdAt=d.updatedAt?new Date(d.updatedAt):new Date();const isNew=available&&(Date.now()-createdAt.getTime())<7*24*60*60*1000;const statusLabel=example?esc(dt('exampleStatus')):d.status==='available'?`${isNew?esc(t('statusNew'))+' ':''}${esc(t('statusAvailable'))}`:d.status==='reserved'?esc(dt('reserved')):d.status==='adopted'?esc(dt('adopted')):esc(t('statusDraft'));const arrivalDate=d.arrivalDate?`<div class="detail"><strong>${esc(t('arrivalLabel'))}</strong>${esc(d.arrivalDate)}</div>`:'';const shareButtons=available?`<div class="profile-share"><span class="share-label">${esc(t('shareTitle'))}</span><div class="share-buttons"><a class="share-button whatsapp" href="https://wa.me/?text=${encodeURIComponent(document.title+' - '+location.href)}" target="_blank" rel="noopener" aria-label="WhatsApp"><span aria-hidden="true">💬</span> ${esc(t('whatsappButton'))}</a><a class="share-button facebook" href="https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(location.href)}" target="_blank" rel="noopener" aria-label="Facebook"><span aria-hidden="true">📘</span> Facebook</a><a class="share-button instagram" href="https://www.instagram.com/" target="_blank" rel="noopener" aria-label="Instagram"><span aria-hidden="true">📷</span> Instagram</a></div></div>`:'';const expressForm=available?`<section id="express-interest" class="form-card express-form"><h2>${esc(t('expressTitle'))}</h2><p class="muted">${esc(t('expressLead'))}</p><form id="express-form" novalidate><div class="field"><label for="express-email">${esc(t('email'))}</label><input id="express-email" type="email" required autocomplete="email"></div><div class="field"><label for="express-dog">${esc(t('expressDog'))}</label><input id="express-dog" type="text" value="${esc(d.name)}" readonly></div><button type="submit" class="button">${esc(t('expressSubmit'))}</button><p id="express-result" role="status" aria-live="polite"></p></form></section>`:'';const trustLine=`<p class="trust-line">${esc(t('trustLine'))}</p>`;shell(`<main class="wrap"><a class="tiny" href="/dogs.html">← ${esc(t('back'))}</a><section class="profile-layout">${profileGallery(d,example)}<div><div class="eyebrow status-badge status-${esc(d.status==='available'&&isNew?'new':d.status)}">${statusLabel}</div><h1 class="profile-title">${esc(d.name)}</h1>${example?`<div class="notice">${esc(t('exampleOnly'))}</div>`:''}${arrivalDate}<p class="profile-copy">${esc(d.description||'')}</p><div class="detail-grid">${profileRows(d)}</div>${profileHealth(d)}${shareButtons}${trustLine}</div></section>${expressForm}${available?window.profileAdoptionCta(d):''}<div id="sticky-cta" class="sticky-cta" hidden><a class="button profile-apply-button" href="/application.html?dogId=${encodeURIComponent(d.id)}">${esc(t('adopt'))} <span aria-hidden="true">→</span></a></div></main>`);let touchStartX=0;const mainPhoto=document.getElementById('profile-main-photo');if(mainPhoto&&photoSources.length>1){mainPhoto.addEventListener('touchstart',e=>{touchStartX=e.touches[0].clientX},{passive:true});mainPhoto.addEventListener('touchend',e=>{const diff=touchStartX-e.changedTouches[0].clientX;if(Math.abs(diff)>50){const idx=photoSources.indexOf(mainPhoto.src);const next=diff>0?Math.min(idx+1,photoSources.length-1):Math.max(idx-1,0);if(next!==idx){const btn=[...document.querySelectorAll('[data-photo-index]')].find(b=>Number(b.dataset.photoIndex)===next);if(btn)btn.click()}}},{passive:true})}const stickyCta=document.getElementById('sticky-cta');if(stickyCta&&available){window.addEventListener('scroll',()=>{const shouldShow=window.scrollY>300&&window.innerWidth<760;stickyCta.hidden=!shouldShow});const updateSticky=()=>{stickyCta.hidden=!(window.scrollY>300&&window.innerWidth<760)};window.addEventListener('resize',updateSticky);updateSticky()}document.querySelectorAll('[data-photo-index]').forEach(button=>button.addEventListener('click',()=>{const src=photoSources[Number(button.dataset.photoIndex)],image=document.getElementById('profile-main-photo');if(!src||!image)return;runTransition(()=>{image.src=src;document.querySelectorAll('[data-photo-index]').forEach(item=>{const active=item===button;item.classList.toggle('is-active',active);item.setAttribute('aria-pressed',String(active))})})}));const expressFormEl=document.getElementById('express-form');if(expressFormEl){expressFormEl.addEventListener('submit',async event=>{event.preventDefault();if(!expressFormEl.reportValidity())return;const result=document.getElementById('express-result');result.className='';result.textContent='';const body={name:d.name,email:document.getElementById('express-email').value.trim(),language:lang,dogId:d.id};try{const statusResponse=await fetch('/api/status');if(!statusResponse.ok||!(await statusResponse.json()).secureEnquiries)throw new Error('secure storage unavailable');const response=await fetch('/api/enquiries',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!response.ok)throw new Error('save failed');const saved=await response.json();if(!saved.saved||saved.delivery!=='encrypted-local-inbox')throw new Error('save failed');result.className='success';result.textContent=t('expressSaved');expressFormEl.reset();document.getElementById('express-dog').value=d.name}catch{result.className='danger';result.textContent=t('expressFailure')}})}bindEnquiryForm()}
async function reviewPage(){let dogs=[];try{dogs=await getDogs('/api/review')}catch{}const drafts=dogs.filter(d=>d.status==='draft');const approved=dogs.filter(d=>d.status==='available'&&!d.example);shell(`<main class="wrap section"><div class="eyebrow">LOCAL ONLY</div><h1 class="section-title">${esc(t('reviewTitle'))}</h1><p class="muted">${esc(t('reviewIntro'))}</p><div class="rule"></div><h2>${esc(t('drafts'))}</h2><div id="drafts">${drafts.length?drafts.map(d=>`<article class="review-card"><div class="eyebrow">${esc(t('statusDraft'))}</div><h3>${esc(d.name)}</h3><p class="meta">${esc(d.age||'')} · ${esc(d.breed||'')} · ${esc(d.location||'')}</p><p>${esc(d.description||'')}</p><div class="pill-row"><span class="pill">${esc(t('temperament'))}: ${esc(d.temperament||'-')}</span><span class="pill">${esc(t('needs'))}: ${esc(d.needs||'-')}</span></div><div class="review-actions"><a class="button secondary small" href="/dog/${encodeURIComponent(d.id)}">${esc(t('profile'))}</a><button class="button small" data-approve="${esc(d.id)}">${esc(t('approve'))}</button></div></article>`).join(''):`<div class="empty-state">${esc(t('noneDrafts'))}</div>`}</div><div class="rule"></div><h2>${esc(t('approved'))}</h2><div>${approved.length?approved.map(d=>`<article class="review-card"><div class="eyebrow">${esc(t('statusAvailable'))}</div><h3>${esc(d.name)}</h3><p>${esc(d.description||'')}</p><a class="button secondary small" href="/dog/${encodeURIComponent(d.id)}">${esc(t('profile'))}</a></article>`).join(''):`<div class="empty-state">-</div>`}</div><p id="review-result" aria-live="polite"></p></main>`);document.querySelectorAll('[data-approve]').forEach(btn=>btn.addEventListener('click',async()=>{if(!confirm(t('approve')+'?'))return;btn.disabled=true;try{const r=await fetch(`/api/review/${encodeURIComponent(btn.dataset.approve)}/approve`,{method:'POST'});if(!r.ok)throw new Error();document.getElementById('review-result').className='success';document.getElementById('review-result').textContent=t('approvedLocal');await reviewPage()}catch{btn.disabled=false;document.getElementById('review-result').className='danger';document.getElementById('review-result').textContent=t('submitError')}}))}
async function render(){document.documentElement.lang=lang;switch(page){case'home':return home();case'dogs':return dogsPage();case'profile':return profilePage();case'review':return reviewPage();case'adoption':return window.adoptionInfoPage();case'application':return window.adoptionApplicationPage();default:return home()}}
function routeName(path){const map={'/':'home','/index.html':'home','/dogs.html':'dogs','/dog.html':'profile','/review.html':'review','/adoption.html':'adoption','/application.html':'application'};if(map[path])return map[path];if(path.startsWith('/dog/'))return 'profile';return null}
const routeTitles={home:'Haneul Tails Rescue | Dog Adoption & Rescue',dogs:'Our Dogs - Haneul Tails Rescue',profile:'Dog Profile - Haneul Tails Rescue',review:'Review Drafts - Haneul Tails Rescue',adoption:'Adoption Information - Haneul Tails Rescue',application:'Adoption Application - Haneul Tails Rescue'};
async function renderLocation(url,scrollTop=false){page=routeName(url.pathname)||page;document.body.dataset.page=page;document.title=routeTitles[page]||'Haneul Tails Rescue';await render();if(scrollTop)window.scrollTo({top:0,behavior:'instant'})}
document.addEventListener('click',event=>{if(event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;const link=event.target.closest('a[href]');if(!link||link.hasAttribute('download')||(link.target&&link.target!=='_self'))return;const target=new URL(link.href,location.href);if(target.origin!==location.origin||!routeName(target.pathname))return;if(target.pathname===location.pathname&&target.search===location.search&&target.hash)return;event.preventDefault();if(target.pathname===location.pathname&&target.search===location.search)return;runTransition(async()=>{history.pushState({},'',target.href);await renderLocation(target,true)})});
window.addEventListener('popstate',()=>{const nextPage=routeName(location.pathname);if(!nextPage)return;runTransition(()=>renderLocation(new URL(location.href),true))});
render();
